CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TYPE notification_type AS ENUM('system','message');
CREATE TABLE profiles(user_id uuid PRIMARY KEY,display_name text, username text);
CREATE TABLE advertiser_accounts(id uuid PRIMARY KEY,user_id uuid,name text,username text,avatar_url text,location text,status text DEFAULT 'active');
CREATE TABLE business_members(business_id uuid,user_id uuid,role text);
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid,type text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE conversation_participants(conversation_id uuid,user_id uuid,business_id uuid,role text DEFAULT 'member',muted boolean DEFAULT false);
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid,sender_id uuid,sender_business_id uuid,content text,is_edited boolean DEFAULT false);
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,type notification_type,title text,body text,actor_id uuid,target_type text,target_id uuid,message_id uuid,is_read boolean DEFAULT false,created_at timestamptz DEFAULT now());
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON notifications FOR ALL USING(user_id=auth.uid());
CREATE FUNCTION public.can_admin_business(p_business_id uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM advertiser_accounts WHERE id=p_business_id AND user_id=auth.uid()) OR EXISTS(SELECT 1 FROM business_members WHERE business_id=p_business_id AND user_id=auth.uid() AND role IN ('owner','admin')) $$;
CREATE FUNCTION public.is_business_member_of(p_business_id uuid,p_user_id uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM advertiser_accounts WHERE id=p_business_id AND user_id=p_user_id) OR EXISTS(SELECT 1 FROM business_members WHERE business_id=p_business_id AND user_id=p_user_id) $$;
CREATE FUNCTION public.can_manage_asset_folder(text) RETURNS boolean LANGUAGE sql AS $$ SELECT can_admin_business($1::uuid) $$;
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid,name text,bucket_id text);
CREATE FUNCTION storage.foldername(text) RETURNS text[] LANGUAGE sql AS $$ SELECT string_to_array($1,'/') $$;
GRANT USAGE ON SCHEMA public,auth,storage TO anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT,INSERT,UPDATE,DELETE ON TABLES TO authenticated,service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated,service_role;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon;
ALTER TABLE conversation_participants ADD COLUMN last_read_at timestamptz;
ALTER TABLE messages ADD COLUMN created_at timestamptz DEFAULT now();
